"use client"

import * as React from "react"

import { PlainTextViewerFrame } from "./plain-text-viewer-frame"
import { PretextMarkdownViewerContent } from "./pretext-markdown-viewer-content"
import { TextViewerFallback } from "./text-viewer-chrome"
import type { TextViewerHandle, TextViewerProps } from "./text-viewer-types"

export type {
  TextDocumentSource,
  TextLineRange,
  TextViewerHandle,
  TextViewerProps,
} from "./text-viewer-types"

export const PretextMarkdownViewer = React.forwardRef<
  TextViewerHandle,
  TextViewerProps
>(function PretextMarkdownViewer(props, ref) {
  return (
    <PlainTextViewerFrame
      props={props}
      forwardedRef={ref}
      clientFallbackPolicy="non-inline-source"
      Fallback={TextViewerFallback}
      Content={PretextMarkdownViewerContent}
    />
  )
})

"use client"

import * as React from "react"

import type { ViewerResource } from "@/lib/viewer-resource"

import {
  createPretextMarkdownDocument,
  findPretextMarkdownHeadingById,
} from "./pretext-markdown-document-model"
import {
  layoutPretextMarkdownDocument,
  type PretextMarkdownChunkFrame,
} from "./pretext-markdown-layout"
import { PretextMarkdownChunkRenderer } from "./pretext-markdown-renderer"
import {
  patchPretextMarkdownChunkTables,
  pretextMarkdownChunkId,
} from "./pretext-markdown-table-accessibility"
import {
  getPretextMarkdownFrameScrollAnchor,
  getPretextMarkdownScrollTopForLineRange,
  getPretextMarkdownSourceLineForScrollTop,
  getPretextMarkdownVisibleChunkFrames,
  markdownChunkIntersectsLineRange,
  resolvePretextMarkdownScrollAnchor,
  type PretextMarkdownScrollAnchor,
} from "./pretext-markdown-virtualizer"
import { ScrollArea } from "./scroll-area"
import { TextViewerFrame, TextViewerToolbar } from "./text-viewer-chrome"
import { normalizeTextLineRange } from "./text-viewer-ranges"
import {
  readTextResource,
  resolvedTextViewerBounds,
  splitTextLines,
} from "./text-viewer-resource"
import { clampTextViewerScale } from "./text-viewer-scale"
import type { TextViewerHandle, TextViewerProps } from "./text-viewer-types"

const VIEWER_HORIZONTAL_PADDING = 16
const DEFAULT_VIEWPORT_HEIGHT = 600
const DEFAULT_VIEWPORT_WIDTH = 800
const INITIAL_CONTENT_WIDTH = 768
const OVERSCAN_PX = 640
const SOURCE_FONT_SIZE = 13
const SOURCE_LINE_HEIGHT = 22
const SOURCE_OVERSCAN_LINES = 24

type PretextMarkdownViewMode = "rendered" | "source"

type ViewportSize = {
  height: number
  width: number
}

export function PretextMarkdownViewerContent({
  resource,
  className,
  toolbar = true,
  highlight,
  bare = false,
  maxBytes,
  maxLines,
  retryVersion,
  forwardedRef,
}: TextViewerProps & {
  resource: ViewerResource
  retryVersion: number
  forwardedRef?: React.ForwardedRef<TextViewerHandle>
}) {
  const bounds = React.useMemo(
    () => resolvedTextViewerBounds({ maxBytes, maxLines }),
    [maxBytes, maxLines]
  )
  const text = React.useMemo(
    () =>
      readTextResource({
        bounds,
        content: resource.content,
        retryVersion,
      }),
    [bounds, resource.content, retryVersion]
  )
  const downloadAction = React.useMemo(
    () => resource.originalDownload,
    [resource]
  )
  const [fontScale, setFontScale] = React.useState(1)
  const [viewMode, setViewMode] =
    React.useState<PretextMarkdownViewMode>("rendered")
  const [scrollTop, setScrollTop] = React.useState(0)
  const [measuredHeights, setMeasuredHeights] = React.useState(
    () => new Map<number, number>()
  )
  const pendingScrollAnchorRef =
    React.useRef<PretextMarkdownScrollAnchor | null>(null)
  const pendingViewModeSourceLineRef = React.useRef<number | null>(null)
  const lastHighlightScrollRef = React.useRef<{
    document: ReturnType<typeof createPretextMarkdownDocument>
    end: number
    start: number
  } | null>(null)
  const resolvedHashRef = React.useRef<string | null>(null)
  const viewportRef = React.useRef<HTMLDivElement | null>(null)
  const fontEpoch = useTextViewerFontEpoch()
  const [contentWidth, setContentWidth] = React.useState(INITIAL_CONTENT_WIDTH)
  const [viewportSize, setViewportSize] = React.useState<ViewportSize>({
    height: 0,
    width: 0,
  })
  const viewportHeight = viewportSize.height || DEFAULT_VIEWPORT_HEIGHT
  const viewportWidth = viewportSize.width || DEFAULT_VIEWPORT_WIDTH

  const document = React.useMemo(
    () => createPretextMarkdownDocument(text),
    [text]
  )
  const isEmptyDocument = text.trim().length === 0
  const sourceLines = React.useMemo(() => splitTextLines(text), [text])
  const sourceLineHeight = SOURCE_LINE_HEIGHT * fontScale
  const frame = React.useMemo(() => {
    void fontEpoch
    return layoutPretextMarkdownDocument({
      contentWidth,
      document,
      fontScale,
      measuredHeights,
    })
  }, [contentWidth, document, fontEpoch, fontScale, measuredHeights])
  const highlightStart = highlight?.start
  const highlightEnd = highlight?.end
  const highlightRange = React.useMemo(
    () =>
      normalizeTextLineRange(
        highlightStart == null || highlightEnd == null
          ? null
          : { end: highlightEnd, start: highlightStart },
        document.sourceLineCount
      ),
    [document.sourceLineCount, highlightEnd, highlightStart]
  )
  const visibleFrames = React.useMemo(
    () =>
      getPretextMarkdownVisibleChunkFrames({
        frames: frame.chunks,
        overscanPx: OVERSCAN_PX,
        scrollTop,
        viewportHeight,
      }),
    [frame.chunks, scrollTop, viewportHeight]
  )

  const captureScrollAnchor = React.useCallback(() => {
    pendingScrollAnchorRef.current = getPretextMarkdownFrameScrollAnchor({
      frames: frame.chunks,
      scrollTop: viewportRef.current?.scrollTop ?? scrollTop,
    })
  }, [frame.chunks, scrollTop])

  React.useLayoutEffect(() => {
    setMeasuredHeights(new Map())
  }, [document])

  React.useLayoutEffect(() => {
    const scrollElement = viewportRef.current
    if (!scrollElement) return

    const readViewportSize = () => {
      const nextWidth = scrollElement.clientWidth
      const nextHeight = scrollElement.clientHeight
      setViewportSize((current) =>
        current.width === nextWidth && current.height === nextHeight
          ? current
          : { height: nextHeight, width: nextWidth }
      )
    }

    readViewportSize()
    const resizeObserver =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(readViewportSize)
    resizeObserver?.observe(scrollElement)

    return () => {
      resizeObserver?.disconnect()
    }
  }, [])

  React.useLayoutEffect(() => {
    const nextContentWidth = Math.max(
      1,
      viewportWidth - VIEWER_HORIZONTAL_PADDING * 2
    )
    setContentWidth((current) => {
      if (current === nextContentWidth) return current
      captureScrollAnchor()
      return nextContentWidth
    })
  }, [captureScrollAnchor, viewportWidth])

  React.useLayoutEffect(() => {
    const anchor = pendingScrollAnchorRef.current
    const scrollElement = viewportRef.current
    if (!anchor || !scrollElement) return

    pendingScrollAnchorRef.current = null
    const nextScrollTop = resolvePretextMarkdownScrollAnchor({
      anchor,
      frames: frame.chunks,
    })
    if (nextScrollTop != null) scrollElement.scrollTop = nextScrollTop
  }, [frame.chunks])

  const recordMeasuredHeight = React.useCallback(
    (chunkIndex: number, height: number) => {
      if (!Number.isFinite(height) || height <= 0) return
      setMeasuredHeights((current) => {
        if (Math.abs((current.get(chunkIndex) ?? 0) - height) < 1) {
          return current
        }
        captureScrollAnchor()
        const next = new Map(current)
        next.set(chunkIndex, height)
        return next
      })
    },
    [captureScrollAnchor]
  )

  const scrollLineRange = React.useCallback(
    (
      range: ReturnType<typeof normalizeTextLineRange>,
      options?: ScrollToOptions
    ) => {
      const scrollElement = viewportRef.current
      if (!scrollElement || !range) return

      if (viewMode === "source") {
        scrollElement.scrollTo(
          createPretextMarkdownScrollOptions({
            options,
            top: Math.max(0, (range.start - 1) * sourceLineHeight),
          })
        )
        return
      }

      const targetTop = getPretextMarkdownScrollTopForLineRange({
        chunks: document.chunks,
        frames: frame.chunks,
        range,
        viewportHeight: scrollElement.clientHeight,
      })
      if (targetTop == null) return

      scrollElement.scrollTo(
        createPretextMarkdownScrollOptions({ options, top: targetTop })
      )
    },
    [document.chunks, frame.chunks, sourceLineHeight, viewMode]
  )
  const scrollLineRangeRef = React.useRef(scrollLineRange)

  React.useLayoutEffect(() => {
    scrollLineRangeRef.current = scrollLineRange
  }, [scrollLineRange])

  const scrollToChunkFrame = React.useCallback(
    (chunkIndex: number, options?: ScrollToOptions) => {
      const scrollElement = viewportRef.current
      const targetFrame = frame.chunks[chunkIndex]
      if (!scrollElement || !targetFrame) return false

      scrollElement.scrollTo(
        createPretextMarkdownScrollOptions({
          options,
          top: Math.max(0, targetFrame.top),
        })
      )
      return true
    },
    [frame.chunks]
  )

  const sourceLineAtScrollTop = React.useCallback(
    (nextScrollTop: number) => {
      if (viewMode === "source") {
        return Math.max(
          1,
          Math.min(
            document.sourceLineCount,
            Math.floor(nextScrollTop / sourceLineHeight) + 1
          )
        )
      }

      return getPretextMarkdownSourceLineForScrollTop({
        chunks: document.chunks,
        frames: frame.chunks,
        scrollTop: nextScrollTop,
      })
    },
    [
      document.chunks,
      document.sourceLineCount,
      frame.chunks,
      sourceLineHeight,
      viewMode,
    ]
  )

  const switchViewMode = React.useCallback(
    (nextMode: PretextMarkdownViewMode) => {
      if (nextMode === viewMode) return

      const scrollElement = viewportRef.current
      if (scrollElement) {
        pendingViewModeSourceLineRef.current = sourceLineAtScrollTop(
          scrollElement.scrollTop
        )
      }
      setViewMode(nextMode)
    },
    [sourceLineAtScrollTop, viewMode]
  )

  const resolveFragmentHref = React.useCallback(
    (href: string, options?: ScrollToOptions) => {
      if (href.length <= 1) return false

      const headingId = decodeMarkdownFragmentHref(href)
      const heading = findPretextMarkdownHeadingById(document, headingId)
      if (!heading) return false

      return scrollToChunkFrame(heading.chunkIndex, options)
    },
    [document, scrollToChunkFrame]
  )

  const resolveCurrentHash = React.useCallback(
    (options?: ScrollToOptions) => {
      const href = window.location.hash
      if (!href || href.length <= 1) return false
      if (resolvedHashRef.current === href) return true
      if (!resolveFragmentHref(href, options)) return false

      resolvedHashRef.current = href
      return true
    },
    [resolveFragmentHref]
  )

  const handleFragmentClick = React.useCallback(
    (event: React.MouseEvent) => {
      const href = localFragmentHrefFromEventTarget(event.target)
      if (!href) return

      if (!resolveFragmentHref(href)) return

      event.preventDefault()
      resolvedHashRef.current = href
      if (window.location.hash !== href) {
        window.history.pushState(null, "", href)
      }
    },
    [resolveFragmentHref]
  )

  const zoom = (factor: number) => {
    captureScrollAnchor()
    setFontScale((scale) => clampTextViewerScale(scale * factor))
  }

  const resetZoom = () => {
    captureScrollAnchor()
    setFontScale(1)
  }

  React.useImperativeHandle(
    forwardedRef ?? null,
    () => ({
      getViewportElement: () => viewportRef.current,
      scrollToLineRange: (range, options) => {
        scrollLineRange(
          normalizeTextLineRange(range, document.sourceLineCount),
          options
        )
      },
    }),
    [document.sourceLineCount, scrollLineRange]
  )

  React.useEffect(() => {
    if (!highlightRange) {
      lastHighlightScrollRef.current = null
      return
    }

    const last = lastHighlightScrollRef.current
    if (
      last &&
      last.document === document &&
      last.start === highlightRange.start &&
      last.end === highlightRange.end
    ) {
      return
    }

    lastHighlightScrollRef.current = {
      document,
      end: highlightRange.end,
      start: highlightRange.start,
    }
    scrollLineRangeRef.current(highlightRange)
  }, [document, highlightRange])

  React.useLayoutEffect(() => {
    const sourceLine = pendingViewModeSourceLineRef.current
    if (sourceLine == null) return

    pendingViewModeSourceLineRef.current = null
    scrollLineRange(
      normalizeTextLineRange(
        { end: sourceLine, start: sourceLine },
        document.sourceLineCount
      ),
      { behavior: "auto" }
    )
  }, [document.sourceLineCount, scrollLineRange, viewMode])

  React.useEffect(() => {
    resolvedHashRef.current = null
  }, [document])

  React.useEffect(() => {
    resolveCurrentHash({ behavior: "auto" })
  }, [resolveCurrentHash])

  React.useEffect(() => {
    const handleFragmentNavigation = () => {
      resolvedHashRef.current = null
      resolveCurrentHash({ behavior: "auto" })
    }

    window.addEventListener("hashchange", handleFragmentNavigation)
    window.addEventListener("popstate", handleFragmentNavigation)
    return () => {
      window.removeEventListener("hashchange", handleFragmentNavigation)
      window.removeEventListener("popstate", handleFragmentNavigation)
    }
  }, [resolveCurrentHash])

  return (
    <TextViewerFrame className={className} bare={bare}>
      {toolbar ? (
        <TextViewerToolbar
          wordCount={document.wordCount}
          fontScale={fontScale}
          leading={
            <PretextMarkdownViewModeControl
              mode={viewMode}
              wordCount={document.wordCount}
              onModeChange={switchViewMode}
            />
          }
          copyLabel="Copy Markdown"
          copyText={document.text}
          downloadAction={downloadAction}
          onZoomOut={() => zoom(1 / 1.2)}
          onZoomIn={() => zoom(1.2)}
          onResetZoom={resetZoom}
        />
      ) : null}
      <ScrollArea
        className="min-h-0 flex-1 bg-background"
        orientation="vertical"
        viewportClassName="bg-background"
        viewportRef={viewportRef}
        viewportProps={{
          onClickCapture:
            viewMode === "rendered" ? handleFragmentClick : undefined,
          onScroll: (event) => {
            setScrollTop(event.currentTarget.scrollTop)
          },
        }}
      >
        {viewMode === "source" ? (
          <PretextMarkdownSourceCanvas
            fontScale={fontScale}
            highlightRange={highlightRange}
            lines={sourceLines}
            scrollTop={scrollTop}
            viewportHeight={viewportHeight}
            viewportWidth={viewportWidth}
          />
        ) : (
          <div
            className="relative min-w-0"
            data-projection="react-gfm-pretext-markdown"
            data-slot="pretext-markdown-virtual-canvas"
            style={{
              height: isEmptyDocument
                ? Math.max(frame.totalHeight, viewportHeight)
                : frame.totalHeight,
              minWidth: viewportWidth,
            }}
          >
            {isEmptyDocument ? (
              <PretextMarkdownEmptyState />
            ) : (
              visibleFrames.map((chunkFrame) => {
                const chunk = document.chunks[chunkFrame.index]
                if (!chunk) return null
                return (
                  <PretextMarkdownChunk
                    key={chunk.index}
                    frame={chunkFrame}
                    highlightRange={highlightRange}
                    highlighted={markdownChunkIntersectsLineRange({
                      chunk,
                      range: highlightRange,
                    })}
                    onMeasuredHeight={recordMeasuredHeight}
                  >
                    <PretextMarkdownChunkRenderer
                      chunk={chunk}
                      footnoteDefinitionsMarkdown={
                        document.footnoteDefinitionsMarkdown
                      }
                      referenceDefinitionsMarkdown={
                        document.referenceDefinitionsMarkdown
                      }
                    />
                  </PretextMarkdownChunk>
                )
              })
            )}
          </div>
        )}
      </ScrollArea>
    </TextViewerFrame>
  )
}

function PretextMarkdownEmptyState() {
  return (
    <div
      aria-label="Empty Markdown document"
      className="absolute inset-x-4 top-0 flex min-h-40 items-center justify-center px-12 text-sm text-muted-foreground"
      data-slot="pretext-markdown-empty-state"
      role="status"
    >
      Empty Markdown document
    </div>
  )
}

function PretextMarkdownViewModeControl({
  mode,
  wordCount,
  onModeChange,
}: {
  mode: PretextMarkdownViewMode
  wordCount: number
  onModeChange: (mode: PretextMarkdownViewMode) => void
}) {
  return (
    <span className="flex min-w-0 items-center gap-2">
      <span className="hidden text-xs text-muted-foreground tabular-nums sm:inline">
        {wordCount} word{wordCount === 1 ? "" : "s"}
      </span>
      <span
        aria-label="Markdown view mode"
        className="inline-flex overflow-hidden rounded-md border bg-muted/35 p-0.5"
        role="group"
      >
        {(["rendered", "source"] as const).map((item) => (
          <button
            key={item}
            aria-pressed={mode === item}
            className={[
              "h-6 px-2 text-xs font-medium capitalize transition-colors",
              mode === item
                ? "rounded-sm bg-background text-foreground shadow-xs"
                : "text-muted-foreground hover:text-foreground",
            ].join(" ")}
            type="button"
            onClick={() => onModeChange(item)}
          >
            {item === "source" ? "Text" : "Rendered"}
          </button>
        ))}
      </span>
    </span>
  )
}

function PretextMarkdownSourceCanvas({
  fontScale,
  highlightRange,
  lines,
  scrollTop,
  viewportHeight,
  viewportWidth,
}: {
  fontScale: number
  highlightRange: ReturnType<typeof normalizeTextLineRange>
  lines: readonly string[]
  scrollTop: number
  viewportHeight: number
  viewportWidth: number
}) {
  const lineHeight = SOURCE_LINE_HEIGHT * fontScale
  const fontSize = SOURCE_FONT_SIZE * fontScale
  const lineCount = Math.max(1, lines.length)
  const startLineIndex = Math.max(
    0,
    Math.floor(scrollTop / lineHeight) - SOURCE_OVERSCAN_LINES
  )
  const endLineIndex = Math.min(
    lineCount,
    Math.ceil((scrollTop + viewportHeight) / lineHeight) + SOURCE_OVERSCAN_LINES
  )
  const visibleLines = lines.slice(startLineIndex, endLineIndex)
  const gutterWidth = Math.max(44, String(lineCount).length * 8 + 24)

  return (
    <div
      aria-label="Markdown source"
      className="relative min-w-0 overflow-x-auto bg-background font-mono text-foreground"
      data-slot="pretext-markdown-source-canvas"
      role="region"
      style={{
        fontSize,
        height: lineCount * lineHeight,
        lineHeight: `${lineHeight}px`,
        minWidth: viewportWidth,
        tabSize: 2,
      }}
      tabIndex={0}
    >
      <div
        aria-hidden="true"
        className="pointer-events-none sticky left-0 z-10 h-full border-r bg-muted/35"
        style={{ width: gutterWidth }}
      />
      {visibleLines.map((line, offset) => {
        const lineIndex = startLineIndex + offset
        const lineNumber = lineIndex + 1
        const highlighted =
          highlightRange != null &&
          lineNumber >= highlightRange.start &&
          lineNumber <= highlightRange.end

        return (
          <div
            key={lineNumber}
            className={[
              "absolute top-0 right-0 left-0 grid whitespace-pre",
              highlighted ? "bg-primary/10 ring-1 ring-primary/20" : "",
            ].join(" ")}
            data-source-line={lineNumber}
            style={{
              gridTemplateColumns: `${gutterWidth}px max-content`,
              height: lineHeight,
              transform: `translateY(${lineIndex * lineHeight}px)`,
            }}
          >
            <span
              aria-hidden="true"
              className="sticky left-0 border-r bg-muted/35 pr-3 text-right text-muted-foreground select-none"
            >
              {lineNumber}
            </span>
            <span className="px-4" data-source-line-content="">
              {line || " "}
            </span>
          </div>
        )
      })}
    </div>
  )
}

function PretextMarkdownChunk({
  children,
  frame,
  highlightRange,
  highlighted,
  onMeasuredHeight,
}: {
  children: React.ReactNode
  frame: PretextMarkdownChunkFrame
  highlightRange: ReturnType<typeof normalizeTextLineRange>
  highlighted: boolean
  onMeasuredHeight: (chunkIndex: number, height: number) => void
}) {
  const ref = React.useRef<HTMLDivElement | null>(null)
  const chunkId = pretextMarkdownChunkId({
    index: frame.index,
    sourceStartLine: frame.sourceStartLine,
  })

  React.useLayoutEffect(() => {
    const element = ref.current
    if (!element) return

    const patchTables = () => {
      patchPretextMarkdownChunkTables({ chunkId, root: element })
    }

    patchTables()
    const mutationObserver =
      typeof MutationObserver === "undefined"
        ? null
        : new MutationObserver(patchTables)
    mutationObserver?.observe(element, {
      childList: true,
      subtree: true,
    })

    if (typeof ResizeObserver === "undefined") {
      return () => {
        mutationObserver?.disconnect()
      }
    }

    const resizeObserver = new ResizeObserver((entries) => {
      const height = entries[0]?.contentRect.height
      patchTables()
      if (height != null) onMeasuredHeight(frame.index, height)
    })
    resizeObserver.observe(element)
    return () => {
      mutationObserver?.disconnect()
      resizeObserver.disconnect()
    }
  }, [chunkId, frame.index, onMeasuredHeight])

  return (
    <div
      ref={ref}
      className={[
        "absolute right-4 left-4 px-12",
        highlighted ? "bg-primary/10 ring-1 ring-primary/25" : "",
      ].join(" ")}
      id={chunkId}
      aria-label={
        highlighted && highlightRange
          ? `Highlighted source lines ${highlightRange.start}-${highlightRange.end}`
          : undefined
      }
      data-pretext-markdown-chunk=""
      data-pretext-markdown-highlighted={highlighted ? "" : undefined}
      data-pretext-markdown-hostile={frame.isHostile ? "" : undefined}
      data-source-highlight-end={
        highlighted && highlightRange ? highlightRange.end : undefined
      }
      data-source-highlight-start={
        highlighted && highlightRange ? highlightRange.start : undefined
      }
      data-source-end-line={frame.sourceEndLine}
      data-source-start-line={frame.sourceStartLine}
      role={highlighted ? "region" : undefined}
      style={{
        minHeight: frame.estimatedHeight,
        transform: `translateY(${frame.top}px)`,
      }}
    >
      {children}
    </div>
  )
}

function localFragmentHrefFromEventTarget(target: EventTarget | null) {
  if (!(target instanceof Element)) return null
  const link = target.closest<HTMLAnchorElement>('a[href^="#"]')
  const href = link?.getAttribute("href") ?? null
  return href && href.length > 1 ? href : null
}

function decodeMarkdownFragmentHref(href: string) {
  try {
    return decodeURIComponent(href.slice(1))
  } catch {
    return href.slice(1)
  }
}

function createPretextMarkdownScrollOptions({
  options,
  top,
}: {
  options?: ScrollToOptions
  top: number
}): ScrollToOptions {
  const behavior = options?.behavior ?? "smooth"
  return {
    ...options,
    behavior:
      behavior === "smooth" && prefersReducedMotion() ? "auto" : behavior,
    top,
  }
}

function prefersReducedMotion() {
  return (
    typeof window !== "undefined" &&
    typeof window.matchMedia === "function" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  )
}

function useTextViewerFontEpoch() {
  const [fontEpoch, setFontEpoch] = React.useState(0)

  React.useEffect(() => {
    const fonts = document.fonts
    if (!fonts) return

    let isMounted = true
    void fonts.ready.then(() => {
      if (isMounted) setFontEpoch((epoch) => epoch + 1)
    })

    return () => {
      isMounted = false
    }
  }, [])

  return fontEpoch
}

"use client"

import {
  parsePretextMarkdownTokens,
  type PretextMarkdownToken,
} from "./pretext-markdown-parser"
import { splitTextLines } from "./text-viewer-resource"

const MARKDOWN_CHUNK_TARGET_SOURCE_LINES = 36
const MARKDOWN_CHUNK_MAX_SOURCE_LINES = 54
const DOM_CLOBBERING_HEADING_IDS = new Set([
  "__proto__",
  "attributes",
  "children",
  "constructor",
  "content",
  "cookie",
  "document",
  "forms",
  "history",
  "id",
  "images",
  "length",
  "links",
  "location",
  "name",
  "navigator",
  "parent",
  "prototype",
  "scripts",
  "self",
  "top",
  "window",
])
const MARKDOWN_HEADING_NAMED_ENTITIES: Record<string, string> = {
  amp: "&",
  apos: "'",
  copy: "©",
  gt: ">",
  hellip: "…",
  laquo: "«",
  ldquo: "“",
  lsquo: "‘",
  lt: "<",
  mdash: "—",
  nbsp: " ",
  ndash: "–",
  quot: '"',
  raquo: "»",
  rdquo: "”",
  reg: "®",
  rsquo: "’",
  shy: "",
  trade: "™",
}

export type PretextMarkdownChunkKind = "frontmatter" | "markdown"
export type PretextMarkdownFrontmatterLanguage = "toml" | "yaml"
export type PretextMarkdownBlockKind =
  | "code"
  | "comment"
  | "definition"
  | "frontmatter"
  | "heading"
  | "html"
  | "list"
  | "paragraph"
  | "table"
  | "thematicBreak"
  | "unknown"

export interface PretextMarkdownDocument {
  blocks: PretextMarkdownBlock[]
  footnoteDefinitionsMarkdown: string
  frontmatter?: PretextMarkdownFrontmatter
  headings: PretextMarkdownHeading[]
  chunks: PretextMarkdownChunk[]
  referenceDefinitionsMarkdown: string
  sourceLineCount: number
  text: string
  wordCount: number
}

export interface PretextMarkdownHeading {
  blockId: string
  id: string
  chunkIndex: number
  sourceOffset: number
  sourceLine: number
  text: string
}

export interface PretextMarkdownFrontmatter {
  entries: PretextMarkdownFrontmatterEntry[]
  language: PretextMarkdownFrontmatterLanguage
  markdown: string
  sourceEndOffset: number
  sourceEndLine: number
  sourceStartOffset: number
  sourceStartLine: number
}

export interface PretextMarkdownFrontmatterEntry {
  key: string
  value: string
  valueKind: "boolean" | "number" | "string"
}

export interface PretextMarkdownBlock {
  chunkIndex: number
  frontmatterEntries?: PretextMarkdownFrontmatterEntry[]
  headingId?: string
  id: string
  index: number
  isOrderedList?: boolean
  isHostile: boolean
  kind: PretextMarkdownBlockKind
  listStart?: number
  markdown: string
  sourceEndOffset: number
  sourceEndLine: number
  sourceStartOffset: number
  sourceStartLine: number
}

export interface PretextMarkdownChunk {
  blockIds: string[]
  frontmatterEntries?: PretextMarkdownFrontmatterEntry[]
  frontmatterLanguage?: PretextMarkdownFrontmatterLanguage
  headingIds: string[]
  index: number
  isHostile: boolean
  kind: PretextMarkdownChunkKind
  markdown: string
  sourceEndOffset: number
  sourceEndLine: number
  sourceStartOffset: number
  sourceStartLine: number
}

export interface PretextMarkdownLineRange {
  end: number
  start: number
}

export interface PretextMarkdownOffsetRange {
  end: number
  start: number
}

export function createPretextMarkdownDocument(
  markdown: string
): PretextMarkdownDocument {
  const sourceLineCount = splitTextLines(markdown).length
  const { blocks, headings, chunks } = createPretextMarkdownChunks(
    markdown,
    sourceLineCount
  )
  const frontmatter =
    chunks[0]?.kind === "frontmatter"
      ? createPretextMarkdownFrontmatter(chunks[0])
      : undefined
  const referenceDefinitionsMarkdown =
    collectPretextMarkdownReferenceDefinitions(markdown)
  const footnoteDefinitionsMarkdown =
    collectPretextMarkdownFootnoteDefinitions(markdown)

  return {
    blocks,
    footnoteDefinitionsMarkdown,
    ...(frontmatter ? { frontmatter } : {}),
    headings,
    chunks,
    referenceDefinitionsMarkdown,
    sourceLineCount,
    text: markdown,
    wordCount: countWords(markdown),
  }
}

export function findPretextMarkdownChunkForLine(
  chunks: readonly PretextMarkdownChunk[],
  sourceLine: number
) {
  return chunks.find(
    (chunk) =>
      chunk.sourceStartLine <= sourceLine && chunk.sourceEndLine >= sourceLine
  )
}

export function findPretextMarkdownChunkForOffset(
  chunks: readonly PretextMarkdownChunk[],
  sourceOffset: number
) {
  return chunks.find((chunk) =>
    pretextMarkdownSourceOffsetsIntersect({
      end: chunk.sourceEndOffset,
      point: sourceOffset,
      start: chunk.sourceStartOffset,
    })
  )
}

export function findPretextMarkdownBlockForOffset(
  blocks: readonly PretextMarkdownBlock[],
  sourceOffset: number
) {
  return blocks.find((block) =>
    pretextMarkdownSourceOffsetsIntersect({
      end: block.sourceEndOffset,
      point: sourceOffset,
      start: block.sourceStartOffset,
    })
  )
}

export function pretextMarkdownChunkIntersectsOffsetRange({
  chunk,
  range,
}: {
  chunk: PretextMarkdownChunk
  range: PretextMarkdownOffsetRange | null
}) {
  return pretextMarkdownSourceRangeIntersectsOffsetRange({
    range,
    sourceEndOffset: chunk.sourceEndOffset,
    sourceStartOffset: chunk.sourceStartOffset,
  })
}

export function pretextMarkdownBlockIntersectsOffsetRange({
  block,
  range,
}: {
  block: PretextMarkdownBlock
  range: PretextMarkdownOffsetRange | null
}) {
  return pretextMarkdownSourceRangeIntersectsOffsetRange({
    range,
    sourceEndOffset: block.sourceEndOffset,
    sourceStartOffset: block.sourceStartOffset,
  })
}

export function findPretextMarkdownHeadingById(
  document: PretextMarkdownDocument,
  headingId: string
) {
  return document.headings.find((heading) => heading.id === headingId)
}

function pretextMarkdownSourceRangeIntersectsOffsetRange({
  range,
  sourceEndOffset,
  sourceStartOffset,
}: {
  range: PretextMarkdownOffsetRange | null
  sourceEndOffset: number
  sourceStartOffset: number
}) {
  if (!range) return false
  const start = Math.max(0, Math.min(range.start, range.end))
  const end = Math.max(0, Math.max(range.start, range.end))
  return sourceStartOffset < end && sourceEndOffset > start
}

function pretextMarkdownSourceOffsetsIntersect({
  end,
  point,
  start,
}: {
  end: number
  point: number
  start: number
}) {
  return point >= start && point < end
}

function createPretextMarkdownChunks(
  markdown: string,
  sourceLineCount: number
): Pick<PretextMarkdownDocument, "blocks" | "headings" | "chunks"> {
  const blockIds: BlockIdRegistry = new Map()
  const blocks: PretextMarkdownBlock[] = []
  const chunks: PretextMarkdownChunk[] = []
  const headings: PretextMarkdownHeading[] = []
  const headingIds: HeadingIdRegistry = new Map()
  const sourceLineOffsets = createSourceLineOffsets(markdown)
  const frontmatter = extractFrontmatter(markdown)
  const body = frontmatter ? frontmatter.body : markdown
  const bodyStartLine = frontmatter ? frontmatter.endLine + 1 : 1

  if (frontmatter) {
    const chunkIndex = chunks.length
    const sourceStartOffset = getSourceLineStartOffset(sourceLineOffsets, 1)
    const sourceEndOffset = getSourceLineEndOffset(
      sourceLineOffsets,
      frontmatter.endLine,
      markdown.length
    )
    const frontmatterEntries = parsePretextMarkdownFrontmatterEntries({
      language: frontmatter.language,
      markdown: frontmatter.text,
    })
    const block = createPretextMarkdownBlock({
      blockIds,
      blocks,
      chunkIndex,
      frontmatterEntries,
      isHostile: false,
      kind: "frontmatter",
      markdown: frontmatter.text,
      sourceEndOffset,
      sourceEndLine: frontmatter.endLine,
      sourceStartOffset,
      sourceStartLine: 1,
    })
    chunks.push({
      blockIds: [block.id],
      frontmatterEntries,
      headingIds: [],
      index: chunkIndex,
      frontmatterLanguage: frontmatter.language,
      isHostile: false,
      kind: "frontmatter",
      markdown: frontmatter.text,
      sourceEndOffset,
      sourceEndLine: frontmatter.endLine,
      sourceStartOffset,
      sourceStartLine: 1,
    })
  }

  const bodyChunks = createMarkdownBodyChunks({
    blockIds,
    blocks,
    headingIds,
    headings,
    markdown: body,
    sourceLineOffsets,
    sourceEndLine: sourceLineCount,
    sourceStartLine: bodyStartLine,
    textLength: markdown.length,
    startIndex: chunks.length,
  })
  chunks.push(...bodyChunks)

  if (!chunks.length) {
    chunks.push({
      blockIds: [],
      headingIds: [],
      index: 0,
      isHostile: false,
      kind: "markdown",
      markdown,
      sourceEndOffset: markdown.length,
      sourceEndLine: sourceLineCount,
      sourceStartOffset: 0,
      sourceStartLine: 1,
    })
  }

  return { blocks, headings, chunks }
}

function createMarkdownBodyChunks({
  blockIds,
  blocks,
  headingIds,
  headings,
  markdown,
  sourceLineOffsets,
  sourceEndLine,
  sourceStartLine,
  textLength,
  startIndex,
}: {
  blockIds: BlockIdRegistry
  blocks: PretextMarkdownBlock[]
  headingIds: HeadingIdRegistry
  headings: PretextMarkdownHeading[]
  markdown: string
  sourceLineOffsets: SourceLineOffsets
  sourceEndLine: number
  sourceStartLine: number
  textLength: number
  startIndex: number
}) {
  const chunks: PretextMarkdownChunk[] = []
  if (!markdown.trim()) return chunks

  try {
    const tokens = parsePretextMarkdownTokens(markdown)
    let cursorLine = sourceStartLine
    let cursorOffset = getSourceLineStartOffset(
      sourceLineOffsets,
      sourceStartLine
    )
    let chunkBlockIds: string[] = []
    let chunkStartLine = sourceStartLine
    let chunkStartOffset = cursorOffset
    let chunkHeadingIds: string[] = []
    let chunkIsHostile = false
    let chunkRaw = ""
    let chunkLineCount = 0

    const flushChunk = (endLine: number) => {
      if (!chunkRaw.trim()) {
        chunkRaw = ""
        chunkLineCount = 0
        chunkIsHostile = false
        chunkStartLine = endLine + 1
        chunkStartOffset = getSourceLineStartOffset(
          sourceLineOffsets,
          chunkStartLine
        )
        return
      }
      const chunkIndex = startIndex + chunks.length
      const chunkMarkdown = chunkRaw.replace(/\n+$/g, "")
      chunks.push({
        blockIds: chunkBlockIds,
        headingIds: chunkHeadingIds,
        index: chunkIndex,
        isHostile: chunkIsHostile,
        kind: "markdown",
        markdown: chunkMarkdown,
        sourceEndOffset: Math.min(
          textLength,
          chunkStartOffset + chunkMarkdown.length
        ),
        sourceEndLine: Math.max(chunkStartLine, endLine),
        sourceStartOffset: chunkStartOffset,
        sourceStartLine: chunkStartLine,
      })
      chunkRaw = ""
      chunkLineCount = 0
      chunkIsHostile = false
      chunkBlockIds = []
      chunkHeadingIds = []
      chunkStartLine = endLine + 1
      chunkStartOffset = getSourceLineStartOffset(
        sourceLineOffsets,
        chunkStartLine
      )
    }

    for (const token of tokens) {
      const raw = token.raw ?? ""
      const tokenLineCount = countLineBreaks(raw)
      const tokenLineBreaks = countLineSeparators(raw)
      const tokenStartLine = cursorLine
      const tokenStartOffset = cursorOffset
      const tokenEndOffset = Math.min(textLength, tokenStartOffset + raw.length)
      const tokenEndLine = Math.min(
        sourceEndLine,
        Math.max(tokenStartLine, cursorLine + Math.max(0, tokenLineCount - 1))
      )
      cursorLine += tokenLineBreaks
      cursorOffset = tokenEndOffset

      if (token.kind === "space") {
        chunkRaw += raw
        chunkLineCount += tokenLineBreaks
        continue
      }

      const tokenIsHostile = isHostilePretextMarkdownToken(token, raw)
      const shouldStartNewChunk =
        chunkRaw.trim().length > 0 &&
        isChunkLeadToken(token) &&
        chunkLineCount >= MARKDOWN_CHUNK_TARGET_SOURCE_LINES
      const wouldExceedMax =
        chunkRaw.trim().length > 0 &&
        chunkLineCount + Math.max(1, tokenLineCount) >
          MARKDOWN_CHUNK_MAX_SOURCE_LINES

      if (shouldStartNewChunk || wouldExceedMax || tokenIsHostile) {
        flushChunk(Math.max(chunkStartLine, tokenStartLine - 1))
        chunkStartLine = tokenStartLine
        chunkStartOffset = tokenStartOffset
      }

      const chunkIndex = startIndex + chunks.length
      const blockKind = pretextMarkdownBlockKindForToken(token)
      const block = createPretextMarkdownBlock({
        blockIds,
        blocks,
        chunkIndex,
        isHostile: tokenIsHostile,
        kind: blockKind,
        markdown: raw,
        sourceEndOffset: tokenEndOffset,
        sourceEndLine: tokenEndLine,
        sourceStartOffset: tokenStartOffset,
        sourceStartLine: tokenStartLine,
      })
      chunkBlockIds.push(block.id)

      if (token.kind === "heading") {
        const text = normalizeHeadingText(token.text)
        const id = createMarkdownHeadingId(text, headingIds)
        block.headingId = id
        chunkHeadingIds.push(id)
        headings.push({
          blockId: block.id,
          id,
          chunkIndex,
          sourceOffset: tokenStartOffset,
          sourceLine: tokenStartLine,
          text,
        })
      }
      if (token.kind === "list") {
        block.isOrderedList = token.isOrderedList
        block.listStart = token.listStart
      }

      chunkRaw += raw
      chunkLineCount += Math.max(1, tokenLineCount)
      chunkIsHostile = chunkIsHostile || tokenIsHostile
      if (tokenIsHostile || chunkLineCount >= MARKDOWN_CHUNK_MAX_SOURCE_LINES) {
        flushChunk(tokenEndLine)
      }
    }

    if (chunkRaw.trim()) {
      flushChunk(sourceEndLine)
    }
  } catch {
    const block = createPretextMarkdownBlock({
      blockIds,
      blocks,
      chunkIndex: startIndex,
      isHostile: isHostilePretextMarkdownChunk(markdown),
      kind: "unknown",
      markdown,
      sourceEndOffset: textLength,
      sourceEndLine,
      sourceStartOffset: getSourceLineStartOffset(
        sourceLineOffsets,
        sourceStartLine
      ),
      sourceStartLine,
    })
    chunks.push({
      blockIds: [block.id],
      headingIds: [],
      index: startIndex,
      isHostile: block.isHostile,
      kind: "markdown",
      markdown,
      sourceEndOffset: block.sourceEndOffset,
      sourceEndLine,
      sourceStartOffset: block.sourceStartOffset,
      sourceStartLine,
    })
  }

  return chunks
}

function extractFrontmatter(markdown: string) {
  const lines = splitTextLines(markdown)
  const openingFence = lines[0]?.trim()
  const language = frontmatterLanguageForFence(openingFence)
  if (!language || !openingFence) return null

  for (let index = 1; index < lines.length; index++) {
    if (lines[index]!.trim() !== openingFence) continue
    if (index === 1) return null
    return {
      body: lines.slice(index + 1).join("\n"),
      endLine: index + 1,
      language,
      text: lines.slice(1, index).join("\n"),
    }
  }

  return null
}

function frontmatterLanguageForFence(
  fence: string | undefined
): PretextMarkdownFrontmatterLanguage | null {
  switch (fence) {
    case "---":
      return "yaml"
    case "+++":
      return "toml"
    default:
      return null
  }
}

function collectPretextMarkdownReferenceDefinitions(markdown: string) {
  const frontmatter = extractFrontmatter(markdown)
  const body = frontmatter ? frontmatter.body : markdown

  try {
    return parsePretextMarkdownTokens(body)
      .filter((token) => token.kind === "definition")
      .map((token) => token.raw.trimEnd())
      .filter(Boolean)
      .join("\n")
  } catch {
    return ""
  }
}

function collectPretextMarkdownFootnoteDefinitions(markdown: string) {
  const frontmatter = extractFrontmatter(markdown)
  const body = frontmatter ? frontmatter.body : markdown

  return splitTextLines(body)
    .map((line) => line.trimEnd())
    .filter((line) => /^\[\^[^\]\r\n]+\]:[ \t]?.+/u.test(line))
    .join("\n")
}

function countLineBreaks(text: string) {
  if (!text) return 1
  return text.split(/\r\n|[\n\r\u2028\u2029]/).length
}

function countLineSeparators(text: string) {
  if (!text) return 0
  return Math.max(0, countLineBreaks(text) - 1)
}

type HeadingIdRegistry = Map<string, number>
type BlockIdRegistry = Map<string, number>

function createPretextMarkdownBlock({
  blockIds,
  blocks,
  chunkIndex,
  frontmatterEntries,
  isHostile,
  kind,
  markdown,
  sourceEndOffset,
  sourceEndLine,
  sourceStartOffset,
  sourceStartLine,
}: {
  blockIds: BlockIdRegistry
  blocks: PretextMarkdownBlock[]
  chunkIndex: number
  frontmatterEntries?: PretextMarkdownFrontmatterEntry[]
  isHostile: boolean
  kind: PretextMarkdownBlockKind
  markdown: string
  sourceEndOffset: number
  sourceEndLine: number
  sourceStartOffset: number
  sourceStartLine: number
}) {
  const block: PretextMarkdownBlock = {
    chunkIndex,
    frontmatterEntries,
    id: createMarkdownBlockId({ blockIds, kind, sourceStartLine }),
    index: blocks.length,
    isHostile,
    kind,
    markdown,
    sourceEndOffset,
    sourceEndLine,
    sourceStartOffset,
    sourceStartLine,
  }
  blocks.push(block)
  return block
}

function createPretextMarkdownFrontmatter(
  chunk: PretextMarkdownChunk
): PretextMarkdownFrontmatter | undefined {
  if (!chunk.frontmatterLanguage) return undefined
  return {
    entries: chunk.frontmatterEntries ?? [],
    language: chunk.frontmatterLanguage,
    markdown: chunk.markdown,
    sourceEndOffset: chunk.sourceEndOffset,
    sourceEndLine: chunk.sourceEndLine,
    sourceStartOffset: chunk.sourceStartOffset,
    sourceStartLine: chunk.sourceStartLine,
  }
}

interface SourceLineOffsets {
  ends: number[]
  starts: number[]
}

function createSourceLineOffsets(text: string): SourceLineOffsets {
  const starts: number[] = []
  const ends: number[] = []
  const lineSeparatorPattern = /\r\n|[\n\r\u2028\u2029]/g
  let lineStart = 0
  let match: RegExpExecArray | null

  while ((match = lineSeparatorPattern.exec(text))) {
    starts.push(lineStart)
    ends.push(match.index)
    lineStart = match.index + match[0].length
  }

  starts.push(lineStart)
  ends.push(text.length)
  return { ends, starts }
}

function getSourceLineStartOffset(offsets: SourceLineOffsets, line: number) {
  return (
    offsets.starts[Math.max(0, line - 1)] ??
    offsets.ends[offsets.ends.length - 1] ??
    0
  )
}

function getSourceLineEndOffset(
  offsets: SourceLineOffsets,
  line: number,
  textLength: number
) {
  return offsets.ends[Math.max(0, line - 1)] ?? textLength
}

function parsePretextMarkdownFrontmatterEntries({
  language,
  markdown,
}: {
  language: PretextMarkdownFrontmatterLanguage
  markdown: string
}): PretextMarkdownFrontmatterEntry[] {
  const entries: PretextMarkdownFrontmatterEntry[] = []
  let isTopLevelToml = true

  for (const line of markdown.split(/\r?\n/)) {
    if (language === "toml" && /^\s*\[/.test(line)) {
      isTopLevelToml = false
      continue
    }

    if (language === "toml" && !isTopLevelToml) continue

    const entry =
      language === "toml"
        ? parsePretextMarkdownTomlFrontmatterEntry(line)
        : parsePretextMarkdownYamlFrontmatterEntry(line)
    if (entry) entries.push(entry)
  }

  return entries
}

function parsePretextMarkdownYamlFrontmatterEntry(
  line: string
): PretextMarkdownFrontmatterEntry | null {
  const trimmed = line.trim()
  if (!trimmed || trimmed.startsWith("#")) return null

  const match = /^([A-Za-z_][\w.-]*)\s*:\s*(.*?)\s*$/.exec(trimmed)
  if (!match) return null
  const value = parsePretextMarkdownFrontmatterScalar(match[2]!)
  if (!value) return null

  return {
    key: match[1]!,
    ...value,
  }
}

function parsePretextMarkdownTomlFrontmatterEntry(
  line: string
): PretextMarkdownFrontmatterEntry | null {
  const trimmed = line.trim()
  if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("[")) {
    return null
  }

  const match = /^([A-Za-z_][\w.-]*)\s*=\s*(.*?)\s*$/.exec(trimmed)
  if (!match) return null
  const value = parsePretextMarkdownFrontmatterScalar(match[2]!)
  if (!value) return null

  return {
    key: match[1]!,
    ...value,
  }
}

function parsePretextMarkdownFrontmatterScalar(
  rawValue: string
): Pick<PretextMarkdownFrontmatterEntry, "value" | "valueKind"> | null {
  const value = rawValue.trim()
  if (!value || /^[{[>|]/.test(value)) return null

  const quoted = /^"([^"]*)"$/.exec(value) ?? /^'([^']*)'$/.exec(value)
  if (quoted) {
    return {
      value: quoted[1]!,
      valueKind: "string",
    }
  }

  if (/^(?:true|false)$/i.test(value)) {
    return {
      value: value.toLowerCase(),
      valueKind: "boolean",
    }
  }

  if (/^-?\d+(?:\.\d+)?$/.test(value)) {
    return {
      value,
      valueKind: "number",
    }
  }

  if (/[:#]/.test(value)) return null

  return {
    value,
    valueKind: "string",
  }
}

function createMarkdownBlockId({
  blockIds,
  kind,
  sourceStartLine,
}: {
  blockIds: BlockIdRegistry
  kind: PretextMarkdownBlockKind
  sourceStartLine: number
}) {
  const base = `block-${sourceStartLine}-${kind}`
  const count = blockIds.get(base) ?? 0
  blockIds.set(base, count + 1)
  return count === 0 ? base : `${base}-${count}`
}

function pretextMarkdownBlockKindForToken(
  token: PretextMarkdownToken
): PretextMarkdownBlockKind {
  switch (token.kind) {
    case "code":
    case "comment":
    case "definition":
    case "heading":
    case "html":
    case "list":
    case "paragraph":
    case "table":
      return token.kind
    case "hr":
      return "thematicBreak"
    default:
      return "unknown"
  }
}

function createMarkdownHeadingId(text: string, headingIds: HeadingIdRegistry) {
  const base = createPretextMarkdownHeadingSlug(text)
  const count = headingIds.get(base) ?? 0
  headingIds.set(base, count + 1)
  return count === 0 ? base : `${base}-${count}`
}

export function createPretextMarkdownHeadingSlug(text: string) {
  return namespaceMarkdownHeadingId(slugifyMarkdownHeading(text))
}

function namespaceMarkdownHeadingId(slug: string) {
  const base = slug || "section"
  return DOM_CLOBBERING_HEADING_IDS.has(base) ? `section-${base}` : base
}

function slugifyMarkdownHeading(text: string) {
  return text
    .trim()
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^\p{Letter}\p{Number}\s_-]/gu, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
}

function normalizeHeadingText(text: string) {
  return decodeMarkdownHeadingEntities(text).replace(/\s+/g, " ").trim()
}

function decodeMarkdownHeadingEntities(text: string) {
  return text.replace(
    /&(#x[\da-f]+|#\d+|[a-z][a-z\d]+);/gi,
    (entity, body: string) => {
      if (body.startsWith("#x") || body.startsWith("#X")) {
        return decodeMarkdownNumericEntity(entity, body.slice(2), 16)
      }
      if (body.startsWith("#")) {
        return decodeMarkdownNumericEntity(entity, body.slice(1), 10)
      }

      return MARKDOWN_HEADING_NAMED_ENTITIES[body.toLowerCase()] ?? entity
    }
  )
}

function decodeMarkdownNumericEntity(
  entity: string,
  rawCodePoint: string,
  radix: number
) {
  const codePoint = Number.parseInt(rawCodePoint, radix)
  if (
    !Number.isFinite(codePoint) ||
    codePoint <= 0 ||
    codePoint > 0x10ffff ||
    (codePoint >= 0xd800 && codePoint <= 0xdfff)
  ) {
    return entity
  }

  try {
    return String.fromCodePoint(codePoint)
  } catch {
    return entity
  }
}

function isChunkLeadToken(token: PretextMarkdownToken) {
  return token.kind === "heading" || token.kind === "hr"
}

export function isHostilePretextMarkdownChunk(markdown: string) {
  try {
    return parsePretextMarkdownTokens(markdown).some((token) =>
      token.kind === "space"
        ? false
        : isHostilePretextMarkdownToken(token, token.raw)
    )
  } catch {
    return markdown.length > 20_000
  }
}

function isHostilePretextMarkdownToken(
  token: PretextMarkdownToken,
  raw: string
) {
  const lineCount = countLineBreaks(raw)

  switch (token.kind) {
    case "code":
      return lineCount > 400
    case "table":
      return Math.max(0, lineCount - 2) > 200
    case "paragraph":
      return raw.length > 20_000
    case "list":
      return lineCount > 500
    case "html":
      return raw.length > 20_000
    default:
      return false
  }
}

function countWords(text: string) {
  return text.trim().split(/\s+/).filter(Boolean).length
}

"use client"

import {
  measureLineStats,
  prepareWithSegments,
  type PreparedTextWithSegments,
} from "@chenglou/pretext"

import type {
  PretextMarkdownBlock,
  PretextMarkdownChunk,
  PretextMarkdownChunkKind,
  PretextMarkdownDocument,
} from "./pretext-markdown-document-model"
import { splitTextLines } from "./text-viewer-resource"

const DOCUMENT_PADDING_Y = 32
const CHUNK_GAP = 0
const CHUNK_PADDING_X = 48
const CHUNK_PADDING_Y = 0
const BODY_LINE_HEIGHT = 24
const CODE_LINE_HEIGHT = 21
const BLOCK_GAP = 8
const MIN_CHUNK_HEIGHT = 120
const BODY_FONT_FAMILY =
  'ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
const CODE_FONT_FAMILY =
  'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace'

export interface PretextMarkdownDocumentFrame {
  chunks: PretextMarkdownChunkFrame[]
  totalHeight: number
  width: number
}

export interface PretextMarkdownChunkFrame {
  blockIds: string[]
  bottom: number
  estimatedHeight: number
  height: number
  index: number
  isHostile: boolean
  kind: PretextMarkdownChunkKind
  measuredHeight: number | null
  sourceEndLine: number
  sourceStartLine: number
  top: number
}

export interface PretextMarkdownMeasuredHeights {
  get(index: number): number | undefined
}

export function layoutPretextMarkdownDocument({
  contentWidth,
  document,
  fontScale,
  measuredHeights,
}: {
  contentWidth: number
  document: PretextMarkdownDocument
  fontScale: number
  measuredHeights?: PretextMarkdownMeasuredHeights
}): PretextMarkdownDocumentFrame {
  const width = Math.max(1, contentWidth)
  const blocksById = new Map(
    document.blocks.map((block) => [block.id, block] as const)
  )
  const frames: PretextMarkdownChunkFrame[] = []
  let y = DOCUMENT_PADDING_Y

  for (const chunk of document.chunks) {
    const measuredHeight = measuredHeights?.get(chunk.index)
    const estimatedHeight = estimatePretextMarkdownChunkHeight({
      blocksById,
      fontScale,
      chunk,
      width,
    })
    const height =
      measuredHeight == null
        ? estimatedHeight
        : Math.max(MIN_CHUNK_HEIGHT, measuredHeight)
    const frame: PretextMarkdownChunkFrame = {
      blockIds: chunk.blockIds,
      bottom: y + height,
      estimatedHeight,
      height,
      index: chunk.index,
      isHostile: chunk.isHostile,
      kind: chunk.kind,
      measuredHeight: measuredHeight ?? null,
      sourceEndLine: chunk.sourceEndLine,
      sourceStartLine: chunk.sourceStartLine,
      top: y,
    }
    frames.push(frame)
    y = frame.bottom + CHUNK_GAP
  }

  return {
    chunks: frames,
    totalHeight: frames.length ? y - CHUNK_GAP + DOCUMENT_PADDING_Y : 0,
    width,
  }
}

export function estimatePretextMarkdownChunkHeight({
  blocksById,
  fontScale,
  chunk,
  width,
}: {
  blocksById?: ReadonlyMap<string, PretextMarkdownBlock>
  fontScale: number
  chunk: PretextMarkdownChunk
  width: number
}) {
  const textWidth = Math.max(1, width - CHUNK_PADDING_X * 2)
  const blocks = chunk.blockIds
    .map((blockId) => blocksById?.get(blockId))
    .filter((block): block is PretextMarkdownBlock => Boolean(block))

  if (blocks.length > 0) {
    return estimatePretextMarkdownBlocksHeight({
      blocks,
      fontScale,
      textWidth,
    })
  }

  if (chunk.isHostile) {
    return estimateHostilePretextMarkdownChunkHeight({
      chunk,
      fontScale,
      textWidth,
    })
  }

  const fontSize = chunk.kind === "frontmatter" ? 13 : 16
  const lineHeight =
    chunk.kind === "frontmatter" ? CODE_LINE_HEIGHT : BODY_LINE_HEIGHT
  const fontFamily =
    chunk.kind === "frontmatter" ? CODE_FONT_FAMILY : BODY_FONT_FAMILY
  const font = `${Math.round(fontSize * fontScale)}px ${fontFamily}`
  const fallbackText = chunk.markdown || " "
  const prepared = prepareWithSegmentsSafe(fallbackText, font, {
    whiteSpace: "pre-wrap",
  })
  const stats = prepared
    ? measureLineStatsSafe(prepared, textWidth / fontScale, fallbackText)
    : estimatePretextMarkdownLineStats(fallbackText, textWidth / fontScale)
  const lineCount = Math.max(1, stats.lineCount)
  const syntaxAllowance = estimateMarkdownSyntaxAllowance(chunk)
  return Math.max(
    MIN_CHUNK_HEIGHT,
    CHUNK_PADDING_Y * 2 + lineCount * lineHeight * fontScale + syntaxAllowance
  )
}

function estimatePretextMarkdownBlocksHeight({
  blocks,
  fontScale,
  textWidth,
}: {
  blocks: readonly PretextMarkdownBlock[]
  fontScale: number
  textWidth: number
}) {
  const visibleBlocks = blocks.filter(isVisiblePretextMarkdownBlock)
  if (!visibleBlocks.length) return 0

  const height = visibleBlocks.reduce(
    (sum, block, index) =>
      sum +
      estimatePretextMarkdownBlockHeight({
        block,
        fontScale,
        textWidth,
      }) +
      (index === visibleBlocks.length - 1 ? 0 : BLOCK_GAP * fontScale),
    CHUNK_PADDING_Y * 2
  )
  return Math.max(MIN_CHUNK_HEIGHT, height)
}

export function estimatePretextMarkdownBlockHeight({
  block,
  fontScale,
  textWidth,
}: {
  block: PretextMarkdownBlock
  fontScale: number
  textWidth: number
}) {
  if (block.kind === "comment" || block.kind === "definition") return 0

  if (block.isHostile) {
    return estimateHostilePretextMarkdownBlockHeight({
      block,
      fontScale,
      textWidth,
    })
  }

  const fontSize = pretextMarkdownBlockFontSize(block)
  const lineHeight = pretextMarkdownBlockLineHeight(block)
  const fontFamily = pretextMarkdownBlockFontFamily(block)
  const font = `${Math.round(fontSize * fontScale)}px ${fontFamily}`
  const fallbackText = block.markdown || " "
  const prepared = prepareWithSegmentsSafe(fallbackText, font, {
    whiteSpace: "pre-wrap",
  })
  const stats = prepared
    ? measureLineStatsSafe(prepared, textWidth / fontScale, fallbackText)
    : estimatePretextMarkdownLineStats(fallbackText, textWidth / fontScale)
  const lineCount = Math.max(1, stats.lineCount)
  return (
    lineCount * lineHeight * fontScale +
    estimatePretextMarkdownBlockSyntaxAllowance(block, fontScale)
  )
}

function estimateHostilePretextMarkdownChunkHeight({
  chunk,
  fontScale,
  textWidth,
}: {
  chunk: PretextMarkdownChunk
  fontScale: number
  textWidth: number
}) {
  const lines = splitTextLines(chunk.markdown || " ")
  const longestLineLength = lines.reduce(
    (maxLength, line) => Math.max(maxLength, line.length),
    1
  )
  const estimatedWrappedLines = Math.max(
    lines.length,
    Math.ceil((longestLineLength * 8 * fontScale) / Math.max(1, textWidth))
  )
  const syntaxAllowance = estimateMarkdownSyntaxAllowance(chunk)

  return Math.max(
    MIN_CHUNK_HEIGHT,
    CHUNK_PADDING_Y * 2 +
      estimatedWrappedLines * BODY_LINE_HEIGHT * fontScale +
      syntaxAllowance
  )
}

function estimateHostilePretextMarkdownBlockHeight({
  block,
  fontScale,
  textWidth,
}: {
  block: PretextMarkdownBlock
  fontScale: number
  textWidth: number
}) {
  const lines = splitTextLines(block.markdown || " ")
  const longestLineLength = lines.reduce(
    (maxLength, line) => Math.max(maxLength, line.length),
    1
  )
  const estimatedWrappedLines = Math.max(
    lines.length,
    Math.ceil((longestLineLength * 8 * fontScale) / Math.max(1, textWidth))
  )

  return (
    estimatedWrappedLines * pretextMarkdownBlockLineHeight(block) * fontScale +
    estimatePretextMarkdownBlockSyntaxAllowance(block, fontScale)
  )
}

function estimateMarkdownSyntaxAllowance(chunk: PretextMarkdownChunk) {
  if (chunk.kind === "frontmatter") return 0
  let allowance = 0
  for (const line of splitTextLines(chunk.markdown)) {
    if (/^#{1,6}\s+/.test(line)) allowance += 18
    if (/^\s*[-*+]\s+/.test(line)) allowance += 3
    if (/^\s*>/.test(line)) allowance += 4
    if (/^\s*\|.*\|\s*$/.test(line)) allowance += 8
    if (/^\s*```/.test(line)) allowance += 16
  }
  return allowance
}

function pretextMarkdownBlockFontSize(block: PretextMarkdownBlock) {
  return isPretextMarkdownCodeLikeBlock(block) ? 13 : 16
}

function pretextMarkdownBlockLineHeight(block: PretextMarkdownBlock) {
  return isPretextMarkdownCodeLikeBlock(block)
    ? CODE_LINE_HEIGHT
    : BODY_LINE_HEIGHT
}

function pretextMarkdownBlockFontFamily(block: PretextMarkdownBlock) {
  return isPretextMarkdownCodeLikeBlock(block)
    ? CODE_FONT_FAMILY
    : BODY_FONT_FAMILY
}

function isPretextMarkdownCodeLikeBlock(block: PretextMarkdownBlock) {
  return (
    block.kind === "code" ||
    block.kind === "frontmatter" ||
    block.kind === "html"
  )
}

function isVisiblePretextMarkdownBlock(block: PretextMarkdownBlock) {
  return block.kind !== "comment" && block.kind !== "definition"
}

function estimatePretextMarkdownBlockSyntaxAllowance(
  block: PretextMarkdownBlock,
  fontScale: number
) {
  switch (block.kind) {
    case "code":
    case "html":
      return 32 * fontScale
    case "frontmatter":
      return 24 * fontScale
    case "heading":
      return 36 * fontScale
    case "list":
      return 12 * fontScale
    case "table":
      return splitTextLines(block.markdown).length * 8 * fontScale
    case "thematicBreak":
      return 28 * fontScale
    default:
      return 0
  }
}

function prepareWithSegmentsSafe(
  text: string,
  font: string,
  options?: Parameters<typeof prepareWithSegments>[2]
) {
  try {
    return prepareWithSegments(text, font, options)
  } catch {
    return null
  }
}

function measureLineStatsSafe(
  prepared: PreparedTextWithSegments,
  width: number,
  fallbackText: string
) {
  try {
    return measureLineStats(prepared, width)
  } catch {
    return estimatePretextMarkdownLineStats(fallbackText, width)
  }
}

function estimatePretextMarkdownLineStats(text: string, width: number) {
  const columns = Math.max(1, Math.floor(width / 8))
  const lines = splitTextLines(text || " ")
  const lineCount = lines.reduce(
    (sum, line) => sum + Math.max(1, Math.ceil((line || " ").length / columns)),
    0
  )
  const maxLineWidth = Math.min(
    width,
    Math.max(...lines.map((line) => (line || " ").length * 8), 1)
  )
  return { lineCount, maxLineWidth }
}

"use client"

import { marked, type Token } from "marked"

export type PretextMarkdownTokenKind =
  | "code"
  | "comment"
  | "definition"
  | "heading"
  | "hr"
  | "html"
  | "list"
  | "paragraph"
  | "space"
  | "table"
  | "other"

export interface PretextMarkdownToken {
  isOrderedList?: boolean
  listStart?: number
  kind: PretextMarkdownTokenKind
  raw: string
  text: string
}

export interface PretextMarkdownParser {
  parse(markdown: string): PretextMarkdownToken[]
}

export const markedPretextMarkdownParser: PretextMarkdownParser = {
  parse(markdown) {
    return marked
      .lexer(markdown, { gfm: true })
      .map((token) => normalizeMarkedToken(token))
  },
}

export function parsePretextMarkdownTokens(markdown: string) {
  return markedPretextMarkdownParser.parse(markdown)
}

function normalizeMarkedToken(token: Token): PretextMarkdownToken {
  return {
    isOrderedList: readMarkedListOrdered(token),
    kind: normalizeMarkedTokenKind(token),
    listStart: readMarkedListStart(token),
    raw: token.raw ?? "",
    text: "text" in token && typeof token.text === "string" ? token.text : "",
  }
}

function readMarkedListOrdered(token: Token) {
  return token.type === "list" ? token.ordered : undefined
}

function readMarkedListStart(token: Token) {
  return token.type === "list" && token.ordered && token.start !== ""
    ? Number(token.start)
    : undefined
}

function normalizeMarkedTokenKind(token: Token): PretextMarkdownTokenKind {
  if (isMarkdownFootnoteDefinition(token.raw ?? "")) return "definition"

  switch (token.type) {
    case "code":
      return "code"
    case "def":
      return "definition"
    case "html":
      return isMarkdownHtmlComment(token.raw ?? "") ? "comment" : "html"
    case "heading":
    case "hr":
    case "list":
    case "paragraph":
    case "space":
    case "table":
      return token.type
    default:
      return "other"
  }
}

function isMarkdownHtmlComment(raw: string) {
  return /^<!--[\s\S]*-->$/.test(raw.trim())
}

function isMarkdownFootnoteDefinition(raw: string) {
  return /^\[\^[^\]\r\n]+\]:[ \t]?/u.test(raw.trimStart())
}

