}

function alertIcon(kind: AlertKind): LucideIcon {
  switch (kind) {
    case "caution":
      return CircleAlert
    case "important":
      return BadgeAlert
    case "note":
      return Info
    case "tip":
      return Lightbulb
    case "warning":
      return TriangleAlert
  }
}
